// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 unlockTime, uint256 depositAmt, uint256 collectAmt) public {
        // Admissible domain: unlockTime in future, deposit amount > 0, collect amount > 0
        vm.assume(collectAmt > 0);
        vm.assume(depositAmt > 0);
        vm.assume(unlockTime > block.timestamp);

        // Actor
        address actor = address(0xbeef);
        vm.deal(actor, depositAmt);

        // Put funds and set unlock time
        vm.prank(actor);
        c.Put{value: depositAmt}(unlockTime);

        // Warp past unlock time
        vm.warp(unlockTime + 1);

        // The contract may have insufficient Ether to cover collectAmt (only depositAmt is present).
        // We try Collect and capture revert.
        vm.prank(actor);
        (bool success,) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, collectAmt));

        // After Collect attempt (whether it succeeded or reverted), the property:
        // The caller's stored balance in Acc must be >= 0 (no underflow).
        // In practice, we check that the returned balance (uint256) is <= original deposit amount
        // because a negative underflow would wrap to a huge number.
        (uint storedTime, uint storedBal) = c.Acc(actor);
        assertTrue(storedBal <= depositAmt);
    }
}

