    function testFuzz_property(uint256 _am, uint256 _deposit, uint256 _unlockTime) public {
        // Restrict to admissible domain: positive withdrawal, sufficient deposit to cover MinSum (1 ether) and _am, unlock time in the past
        _am = bound(_am, 1, type(uint128).max);
        _deposit = bound(_deposit, _am + 1 ether, type(uint128).max);
        _unlockTime = bound(_unlockTime, 0, block.timestamp - 1);

        address actor = address(0x1234);
        vm.deal(actor, _deposit);
        vm.prank(actor);
        c.Put{value: _deposit}(_unlockTime);

        uint256 balanceBefore = c.Acc(actor);

        vm.prank(actor);
        c.Collect(_am);

        uint256 balanceAfter = c.Acc(actor);
        assertTrue(balanceAfter == balanceBefore - _am);
    }
}

