pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 _am, uint256 _unlockTime, uint256 _putAmount) public {
        // restrict to admissible domain: _am must be > 0 and < type(uint256).max to avoid overflow in sum
        bound(_am, 1, 1000 ether);
        bound(_putAmount, 1 ether, 1000 ether);
        // unlockTime must be in the past so Collect can succeed
        vm.assume(_unlockTime < block.timestamp);

        // use two distinct actors: actor1 deposits, actor2 deposits (ensures contract has balance)
        address actor1 = address(0x1001);
        address actor2 = address(0x1002);

        // initial balances
        uint256 bal1Before = c.Acc(actor1).balance;
        uint256 bal2Before = c.Acc(actor2).balance;
        uint256 ethBefore = address(c).balance;
        uint256 sumBefore = bal1Before + bal2Before + ethBefore;

        // actor1 puts ether
        vm.deal(actor1, _putAmount);
        vm.prank(actor1);
        c.Put{value: _putAmount}(_unlockTime);

        // actor2 puts some ether so contract has balance
        vm.deal(actor2, 1 ether);
        vm.prank(actor2);
        c.Put{value: 1 ether}(_unlockTime);

        // actor1 collects _am (must be <= its balance, <= contract balance)
        vm.assume(_am <= _putAmount);
        vm.assume(_am <= address(c).balance);

        vm.prank(actor1);
        // Collect is payable but sends ether out; we call without sending extra value
        c.Collect(_am);

        // after state
        uint256 bal1After = c.Acc(actor1).balance;
        uint256 bal2After = c.Acc(actor2).balance;
        uint256 ethAfter = address(c).balance;
        uint256 sumAfter = bal1After + bal2After + ethAfter;

        // invariant: sum of all Acc balances + contract balance should not increase after a successful Collect
        // The reference subtracts, so sum stays same (ETH out, internal balance down).
        // The bug adds, increasing internal balance without changing ETH balance, increasing sum.
        assertTrue(sumAfter <= sumBefore);
    }
}

