pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _am, uint256 unlockDelay, uint256 depositAmt, address actor) public {
        vm.assume(actor != address(0) && actor != address(this));
        vm.assume(depositAmt > 0 && _am > 0);
        // Ensure deposited amount covers MinSum and the Collect amount
        vm.assume(depositAmt >= c.MinSum() && depositAmt >= _am);
        // Ensure unlock time is in the future but not too far
        vm.assume(unlockDelay > 0 && unlockDelay < 365 days);

        // Fund and Put from actor
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.Put{value: depositAmt}(block.timestamp + unlockDelay);

        // Move time past unlockTime
        vm.warp(block.timestamp + unlockDelay + 1);

        // Snapshot actor's Acc balance and contract ETH balance before Collect
        uint256 balBefore = c.Acc(actor).balance;
        uint256 ethBefore = address(c).balance;
        uint256 sumBefore = balBefore + ethBefore;

        // Collect
        vm.prank(actor);
        c.Collect(_am);

        // After Collect
        uint256 balAfter = c.Acc(actor).balance;
        uint256 ethAfter = address(c).balance;
        uint256 sumAfter = balAfter + ethAfter;

        // Sum of actor's internal balance + contract ETH must not increase
        assertTrue(sumAfter <= sumBefore);
    }
}
